def predict(probe):
    # Rule: split on whitespace, reverse each token, join with single space.
    # If input does NOT end with whitespace, prepend a copy of the first char
    # of the last reversed token (= last char of original last word).
    # If input ends with whitespace, no duplication.
    # Evidence: E1,E2,E3,E4,E5,E6,E7,E8,E9,E10,E11,E12
    out = []
    for s in probe.get("inputs", []):
        try:
            tokens = s.split()
            if not tokens:
                out.append("")
                continue
            rev = [t[::-1] for t in tokens]
            if s and s[-1].isspace():
                out.append(" ".join(rev))
            else:
                last = rev[-1]
                rev[-1] = last[0] + last
                out.append(" ".join(rev))
        except Exception:
            out.append("")
    return {"outputs": out}
